import fs from "node:fs";
import path from "node:path";

// The index of authorities (SITE-PLAN Phase 4), generated by
// tools/build-index-json.py from index/authorities.tsv. The files are read from disk
// at BUILD time, never imported: Augustine's file alone is ~2 MB, and an import would
// inline it into every page that touches it.

export type AuthLocus = {
  chunk: string;
  url: string;
  title: string;
  work: string; // the Bonaventure work the citation is in
  division: string;
  book: string; // book numeral of the CITED work, if printed
  locus: string; // as printed by Quaracchi
  key: string; // sort key
  role: "cited" | "same-passage";
  pseudo: boolean;
  named: boolean; // author named in Bonaventure's text, not in the note
  inherited: boolean; // loc. cit. / ibid.
  raw: string;
};

export type AuthWork = {
  id: string;
  la: string;
  en: string;
  pseudo: boolean;
  count: number;
  cited: number;
  samePassage: number;
  loci: AuthLocus[];
};

export type AuthAuthor = { id: string; la: string; en: string; count: number; works: AuthWork[] };

export type TocAuthor = {
  id: string;
  la: string;
  en: string;
  count: number;
  cited: number;
  samePassage: number;
  works: { id: string; la: string; count: number }[];
};

const DATA = path.join(process.cwd(), "src", "data");

function must(file: string) {
  if (!fs.existsSync(file)) {
    // FAIL LOUDLY: an empty index would build "successfully" with no pages.
    throw new Error(
      `${path.basename(file)} is missing. Run tools/build-authorities.py, then `
      + "tools/build-index-json.py, before building.",
    );
  }
  return JSON.parse(fs.readFileSync(file, "utf-8"));
}

let tocCache: TocAuthor[] | null = null;
export function authorityToc(): TocAuthor[] {
  if (!tocCache) tocCache = must(path.join(DATA, "index-authorities-toc.json")).authors as TocAuthor[];
  return tocCache;
}

const authorCache = new Map<string, AuthAuthor>();
export function loadAuthor(id: string): AuthAuthor | null {
  if (!/^[a-z0-9-]+$/.test(id)) return null;
  const file = path.join(DATA, "authorities", `${id}.json`);
  if (!fs.existsSync(file)) return null;
  if (!authorCache.has(id)) authorCache.set(id, JSON.parse(fs.readFileSync(file, "utf-8")));
  return authorCache.get(id)!;
}

let chunkCache: Record<string, [string, string, number][]> | null = null;
export function authoritiesInChunk(chunkId: string): [string, string, number][] {
  if (!chunkCache) chunkCache = must(path.join(DATA, "authorities-by-chunk.json")).chunks;
  return chunkCache![chunkId] ?? [];
}

/** The printed locus with its book numeral, e.g. "XII, c. 19. n. 24". */
export function locusLabel(l: AuthLocus) {
  const roman = l.book ? toRoman(Number(l.book)) : "";
  if (l.role === "same-passage" && !l.locus) return "on this passage";
  return [roman, l.locus].filter(Boolean).join(", ") || "—";
}

function toRoman(n: number) {
  if (!n) return "";
  const t: [number, string][] = [
    [1000, "M"], [900, "CM"], [500, "D"], [400, "CD"], [100, "C"], [90, "XC"],
    [50, "L"], [40, "XL"], [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"],
  ];
  let out = "";
  for (const [v, s] of t) while (n >= v) { out += s; n -= v; }
  return out;
}

export const UNASSIGNED = "unassigned";
